{
  "candidates": [
    {
      "explanation": "Moderate pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, increase when backlog is high and pipeline is low. Node-specific thresholds.",
      "rules": [
        {
          "when": "agent==0 and backlog>0 and pipeline<10",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==0 and pipeline>15 and backlog==0",
          "delta": "-2"
        },
        {
          "when": "agent==1 and backlog>0 and pipeline<20",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==1 and pipeline>30 and backlog==0",
          "delta": "-2"
        },
        {
          "when": "agent==2 and backlog>0 and pipeline<20",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==2 and pipeline>30 and backlog==0",
          "delta": "-2"
        }
      ]
    },
    {
      "explanation": "Aggressive backlog clearing: increase orders when backlog exists, especially if pipeline is low. Reduce orders when pipeline is very high and no backlog.",
      "rules": [
        {
          "when": "backlog>0 and pipeline<15",
          "delta": "min(6, backlog*2)"
        },
        {
          "when": "backlog>0 and pipeline>=15",
          "delta": "min(6, backlog)"
        },
        {
          "when": "backlog==0 and pipeline>25",
          "delta": "-3"
        }
      ]
    },
    {
      "explanation": "Demand-responsive: increase orders when recent demand exceeds baseline (growth>1), decrease when growth<1. Also consider backlog and pipeline.",
      "rules": [
        {
          "when": "growth>1.1 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "growth>1.1 and backlog==0 and pipeline<10",
          "delta": "2"
        },
        {
          "when": "growth<0.9 and pipeline>20",
          "delta": "-2"
        },
        {
          "when": "backlog>0 and pipeline<10",
          "delta": "min(6, backlog)"
        }
      ]
    }
  ]
}

