          "when": "agent==0 and growth<0.8 and pipeline>50",
          "delta": "-2"
        },
        {
          "when": "agent==1 and growth>1.2 and backlog>0",
          "delta": "1"
        },
        {
          "when": "agent==1 and growth<0.8 and pipeline>70",
          "delta": "-1"
        },
        {
          "when": "agent==2 and growth>1.2 and backlog>0",
          "delta": "1"
        },
        {
          "when": "agent==2 and growth<0.8 and pipeline>70",
          "delta": "-1"
        }
      ]
    },
